// LoadCreatedByMember loads the documentConfirmation's CreatedByMember into the .R struct
func (os DocumentConfirmationSlice) LoadCreatedByMember(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	members, err := os.CreatedByMember(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.CreatedByMember = nil
		o.R.Loaded.CreatedByMember = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	documentConfirmationByKey := make(map[uuid.UUID][]*DocumentConfirmation, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		documentConfirmationByKey[o.CreatedBy] = append(documentConfirmationByKey[o.CreatedBy], o)
	}

	for _, rel := range members {

		owners, ok := documentConfirmationByKey[rel.ID]
		if !ok {
			continue
		}

		for _, o := range owners {

			// to-one: keep only the first matching child (matches the previous break)
			if o.R.CreatedByMember != nil {
				continue
			}

			rel.R.CreatedByDocumentConfirmations = append(rel.R.CreatedByDocumentConfirmations, o)

			o.R.CreatedByMember = rel

		}
	}

	return nil
}

